func halvingSteps(count: Int) -> Int {
    var size = count
    var steps = 0
    while size > 1 {
        size /= 2
        steps += 1
    }
    return steps
}
print(halvingSteps(count: 8))
print(halvingSteps(count: 1024))
print(halvingSteps(count: 1_000_000))

